-- 7 days ago (the restaurant has been running 1 week)
INSERT INTO table_session (id, table_id, restaurant_id, guest_count, opened_at, closed_at)
SELECT
  s.id, t.id, 3, 2 + (s.n % 4),
  (CURRENT_TIMESTAMP - INTERVAL '7 days' + (s.n * INTERVAL '90 minutes')),
  (CURRENT_TIMESTAMP - INTERVAL '7 days' + ((s.n+1) * INTERVAL '90 minutes'))
FROM dining_table t
