  CASE WHEN s.n % 5 = 0 THEN 8.58
       WHEN s.n % 5 = 1 THEN 6.60
       WHEN s.n % 5 = 2 THEN 11.16
       WHEN s.n % 5 = 3 THEN 5.50
       ELSE 15.78
  END,
  0.00,
  'PAID',
  (CURRENT_TIMESTAMP - INTERVAL '7 days' + (s.n * INTERVAL '90 minutes'))
FROM generate_series(1, 20) AS s(n)
