-- ── INVENTORY LEDGER — initial opening stock ────────────────────────────────
-- event_type values (from StockMovementType enum):
--   OPENING_STOCK   ← opening count for new restaurant
--   RECEIVING       ← shipment intake from GRN
--   DEPLETION       ← POS-driven recipe consumption
--   ADJUSTMENT      ← manual count corrections
--   PRODUCTION_IN   ← prepped stock from batching
--
-- All 20 ingredients receive opening stock equal to par_level.
-- unit_cost = purchase_unit_price per PU (same as ingredient.purchase_unit_price).
-- par_level is set on the ingredient itself (restocked when on_hand ≤ par * 0.5).
--
-- The ledger is an AUDIT log — each movement is one row.
-- total_value = quantity_change × unit_cost (PostgreSQL will calculate if column is COMPUTED,
-- otherwise we set it explicitly here).
INSERT INTO inventory_ingredient_ledger
  (id, restaurant_id, ingredient_id, event_type, quantity_change,
   unit_cost, total_value, reason, recorded_at, created_at)
SELECT
  3000 + i.n,
  3, i.id,
  'OPENING_STOCK',
  -- opening stock = par_level (restaurant starts fully stocked)
  i.par_level,
  i.purchase_unit_price,
  -- total_value = par_level × unit_cost (round to 4 dp)
  round(i.par_level * i.purchase_unit_price, 4),
  'Initial opening stock — The Market Table Restaurant',
  '2026-01-01',
  '2026-01-01'
FROM generate_series(301, 320) AS i(n)
JOIN ingredient ing ON ing.id = i.n
ON CONFLICT DO NOTHING;


